// Same vectors as the Rust test `matches_reference_vectors` (desktop/src/net.rs),
// generated by tools/vectors.py. If these pass on both sides, phone and PC agree.

import 'package:flutter_test/flutter_test.dart';
import 'package:nexus_mobile/protocol.dart';

void main() {
  test('matches reference vectors', () async {
    final ska = await keyPairFromSeed(List.filled(32, 1));
    final skb = await keyPairFromSeed(List.filled(32, 2));
    final pka = await publicKeyOf(ska);
    final pkb = await publicKeyOf(skb);
    expect(toHex(pka), 'a4e09292b651c278b9772c569f5fa9bb13d906b46ab68c9df9dc2b4409f8a209');
    expect(toHex(pkb), 'ce8d3ad1ccb633ec7b70c17814a5c76ecd029685050d344745ba05870e587d59');

    final idA = await idFor(pka);
    final idB = await idFor(pkb);
    expect(idA, '1a92f23852dc908d');
    expect(idB, 'cfa570c653bd212b');

    final na = List<int>.generate(32, (i) => i);
    final nb = List<int>.generate(32, (i) => 32 + i);
    expect(toHex(await commitment(nb, pkb, pka)), '9c0b7658fab2384bcc81d1279ce676053ed9a0d14a0b44e2875ded18404c9d9a');
    expect(await pairingCode(pka, pkb, na, nb), '991548');

    final dh = await sharedSecret(ska, pkb);
    expect(toHex(dh), '2ed76ab549b1e73c031eb49c9448f0798aea81b698279a0c3dc3e49fbfc4b953');
    expect(toHex(await sharedSecret(skb, pka)), toHex(dh));

    final nonce = List<int>.generate(16, (i) => i);
    expect(toHex(await pingMac(dh, nonce, idB, idA)), 'a0076a3d95367e6269cde514a4ad868319a11736f150dffccee35f1d4f2f0027');
    expect(toHex(await statsMac(dh, nonce, '{"cpu":12.5,"ram":40.0,"battery":null}')),
        'c907b8868f50ad65d246b1ea19b8c3cbb77290a2c185394f93b4901741739935');
    expect(toHex(await commandMac(dh, nonce, 'restart', idB, idA)),
        'cc23f5b317576fbab9eaeb6679cccb8505c71920ff2e9f84994ee520f2b3719a');
    expect(toHex(await commandAckMac(dh, nonce, 'ok')),
        '0d7987eada42979766a460a96ea74e2981dedf85e6ecb4af3573d20fdfb63344');
  });

  test('hex helpers', () {
    expect(fromHex('00ff10'), [0, 255, 16]);
    expect(() => fromHex('abc'), throwsA(isA<NexusError>()));
    expect(() => fromHex('zz'), throwsA(isA<NexusError>()));
    expect(sameBytes([1, 2, 3], [1, 2, 3]), isTrue);
    expect(sameBytes([1, 2, 3], [1, 2, 4]), isFalse);
  });

  test('mac parsing', () {
    expect(parseMac('aa:bb:cc:dd:ee:ff'), [0xaa, 0xbb, 0xcc, 0xdd, 0xee, 0xff]);
    expect(parseMac('00-00-00-00-00-00'), isNull);
    expect(parseMac('not a mac'), isNull);
  });
}
